--region import
--endregion import

--region define
--endregion define

---@class CommonSliderNode
--- from: Assets/BundleResources/Prefabs/OverseaStore/OverseaStoreCoreExchangeDialog.prefab
---@field Env                           	CommonSliderNode                        
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field TextNumber                    	UnityEngine.RectTransform               
---@field TextNumberRight               	UnityEngine.RectTransform               
---@field TextNumberLeft                	UnityEngine.RectTransform               
---@field BtnAddBg                      	UnityEngine.RectTransform               
---@field BtnAdd                        	Engine.UI.ButtonLongPress               
---@field BtnReduceBg                   	UnityEngine.RectTransform               
---@field BtnReduce                     	Engine.UI.ButtonLongPress               
---@field Slider                        	UnityEngine.UI.Slider               
local CommonSliderNode = Class("CommonSliderNode")

--region lifecycle
function CommonSliderNode:__init()
    self._changedCB = nil -- 数值变动回调

end

function CommonSliderNode:__delete()
    self._changedCB = nil
end

function CommonSliderNode:Awake()
    self:InitHandler()
    self:InitData()
end

function CommonSliderNode:Start()

end

function CommonSliderNode:OnDestroy()
    self.Slider.onValueChanged:RemoveAllListeners()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
--endregion lifecycle

--region init
function CommonSliderNode:InitHandler()
    self.Slider.onValueChanged:AddListener(Bind(self, self.SliderValueChangedHandler))
    self.BtnAdd.onClick = Bind(self, self.BtnAddOnClickHandler)
    self.BtnAdd.onFixLongPress = Bind(self, self.BtnAddOnClickHandler)
    self.BtnReduce.onClick = Bind(self, self.BtnReduceOnclickHandler)
    self.BtnReduce.onFixLongPress = Bind(self, self.BtnReduceOnclickHandler)
end

function CommonSliderNode:InitData()
end
--endregion init

--region handler
---滑动条数值变动处理
function CommonSliderNode:SliderValueChangedHandler(value)
    CfUtils.FillText(self.TextNumber, checkInt(value))
    CfUtils.SetUISwitchImage(self.BtnReduceBg, (value <= self.Slider.minValue) and 2 or 1)
    CfUtils.SetUISwitchImage(self.BtnAddBg, (value >= self.Slider.maxValue) and 2 or 1)
    if self._changedCB then
        self._changedCB(checkInt(value))
    end
end

function CommonSliderNode:SetTextNumber(value)
    CfUtils.FillText(self.TextNumber, checkInt(value))
end

---增加按钮点击回调
function CommonSliderNode:BtnAddOnClickHandler(value)
    local changeNum = value or 1
    local num = math.min(self.Slider.maxValue, self.Slider.value + changeNum)
    self:SetValue(num)
end

---减少按钮点击回调
function CommonSliderNode:BtnReduceOnclickHandler(value)
    local changeNum = value or 1
    local num = math.max(0, self.Slider.value - changeNum)
    self:SetValue(num)
end
--endregion handler

--region public
---刷新节点
---@param value number 当前值
---@param min number 最小值
---@param max number 最大值
---@param cb function 变动回调
function CommonSliderNode:RefreshNode(value, min, max, cb)
    CfUtils.FillText(self.TextNumberLeft, min or 0)
    CfUtils.FillText(self.TextNumberRight, max)
    self.Slider.maxValue = max
    if min == max then
        -- 为了让相同值进度条在右侧
        self.Slider.minValue = min - 0.1
    else
        self.Slider.minValue = min or 0
    end
    self._changedCB = cb
    self:SetValue(value)
end

function CommonSliderNode:SetValue(value)
    self.Slider.value = value
end
--endregion public

--region private
--endregion private

return CommonSliderNode